from typing import List, Dict, Any, Tuple, Set

# ---- Helper functions ----------------------------------------------------
def node_by_title(doc: Dict[str, Any], title: str):
    for node in doc['nodes']:
        if node['title'] == title:
            return node

def node_by_id(doc: Dict[str, Any], node_id: str):
    for node in doc['nodes']:
        if node['node_id'] == node_id:
            return node

def children(doc: Dict[str, Any], node):
    return [node_by_id(doc, cid) for cid in node.get('children', [])]

def scope_nodes(doc: Dict[str, Any], scope: str):
    """Return the direct child nodes of a scope title."""
    root = node_by_title(doc, scope)
    return children(doc, root)

def table_rows(node: Dict[str, Any]):
    rows = []
    idx = 0
    for r in node['table']['rows']:
        row = {}
        for col, cell in zip(node['table']['columns'], r):
            row[col] = cell
        rows.append((idx, row))
        idx += 1
    return rows

# ---- Utility -------------------------------------------------------------
def _numeric_value(cell: str):
    """Attempt to parse a numeric value from a cell string."""
    if not isinstance(cell, str):
        return None
    # Remove currency symbols, parentheses, commas, dashes
    c = cell.replace('$', '').replace('£', '').replace('€', '').replace('—', '').replace('–', '-')
    c = c.replace('(', '-').replace(')', '')  # negative numbers
    c = c.replace(',', '').strip()
    if c == '' or c == '-':
        return None
    try:
        return float(c)
    except ValueError:
        return None

def _extract_year(header: str) -> int | None:
    """Extract a year from a table column header."""
    m = re.search(r'(\d{4})', header)
    if m:
        yr = int(m.group(1))
        if 1900 <= yr <= 2100:
            return yr
    return None

# ---- Main functions -------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return distinct entities in the scope."""
    seen: Set[str] = set()
    res: List[Dict[str, str]] = []
    for node in scope_nodes(doc, scope):
        if node.get('kind') == 'table':
            for _, row in table_rows(node):
                ent = row.get('col0', '').strip()
                if ent and ent not in seen:
                    seen.add(ent)
                    res.append({'id': ent, 'description': ent})
        elif node.get('kind') == 'list':
            # For list lines, each line may be an entity if it contains a dash
            for line in node.get('lines', []):
                parts = line.split(' - ')
                if parts:
                    ent = parts[0].strip()
                    if ent and ent not in seen:
                        seen.add(ent)
                        res.append({'id': ent, 'description': ent})
    return res

def recorded_end(doc: Dict[str, Any], scope: str) -> float | None:
    """Return the latest year appearing in the scope."""
    max_year: int | None = None
    for node in scope_nodes(doc, scope):
        if node.get('kind') == 'table':
            for col in node['table']['columns']:
                yr = _extract_year(col)
                if yr is not None and (max_year is None or yr > max_year):
                    max_year = yr
    if max_year is None:
        return None
    return float(max_year)

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all readings that are considered inputs."""
    # In this simplified implementation we assume no explicit inputs
    # other than the starting balances in tables. We return the
    # first row of each table where the row index is 0.
    res: List[Dict[str, Any]] = []
    for node in scope_nodes(doc, scope):
        if node.get('kind') == 'table':
            rows = table_rows(node)
            if not rows:
                continue
            row_index, row = rows[0]
            ent_ids = [row.get('col0')] if row.get('col0') else []
            fields = {}
            for col, cell in row.items():
                if col == 'col0':
                    continue
                val = _numeric_value(cell)
                if val is not None:
                    fields[col] = val
            src = [[node['node_id'], row_index]]
            inp = {
                'id': f'inp_{node["node_id"]}_{row_index}',
                'time': None,
                'kind': 'balance',
                'entities': [e for e in ent_ids if e],
                'fields': fields,
                'src': src
            }
            res.append(inp)
    return res

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all measurements/events that are considered outcomes."""
    res: List[Dict[str, Any]] = []
    oid = 0
    for node in scope_nodes(doc, scope):
        if node.get('kind') != 'table':
            continue
        columns = node['table']['columns']
        col_years = [_extract_year(c) for c in columns]
        for row_index, row in table_rows(node):
            ent_ids = [row.get('col0')] if row.get('col0') else []
            for col_index, col in enumerate(columns):
                val = _numeric_value(row.get(col, ''))
                # Skip heading row or non‑numeric cells unless we treat them as events
                if val is None:
                    continue
                time = col_years[col_index]
                src = [[node['node_id'], row_index, [col]]]
                res.append({
                    'time': time,
                    'kind': 'measurement',
                    'entities': [e for e in ent_ids if e],
                    'value': val,
                    'src': src
                })
                oid += 1
    return res

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constants found in the scope. None for this data set."""
    return {}

